const TOKEN_TTL_MS = 60 * 60 * 1000;

export interface Token {
  value: string;
  issuedAt: number;
}

export function isExpired(token: Token, now = Date.now()): boolean {
  return now - token.issuedAt > TOKEN_TTL_MS;
}

export function parseBearer(header: string | undefined): string | null {
  if (!header) return null;
  const [scheme, value] = header.split(' ');
  return scheme === 'Bearer' && value ? value : null;
}

export function authenticate(header: string | undefined, tokens: Map<string, Token>): boolean {
  const value = parseBearer(header);
  if (!value) return false;
  const token = tokens.get(value);
  return token !== undefined && !isExpired(token);
}
